pub(crate) fn find(key: &str) -> Option<&'static str> {
    if key >= "подтяпавший" {
        return m39(key);
    }
    if key >= "подмокавший" {
        return m38(key);
    }
    if key >= "подавивший" {
        return m37(key);
    }
    if key >= "пинаемый" {
        return m36(key);
    }
    if key >= "пересахаривавший" {
        return m35(key);
    }
    if key >= "перекрывающий" {
        return m34(key);
    }
    if key >= "перебрасываемый" {
        return m33(key);
    }
    if key >= "отчитанный" {
        return m32(key);
    }
    if key >= "отпорхнувший" {
        return m31(key);
    }
    if key >= "отесывавший" {
        return m30(key);
    }
    if key >= "оседлываемый" {
        return m29(key);
    }
    if key >= "окармливавший" {
        return m28(key);
    }
    if key >= "обстряпывавший" {
        return m27(key);
    }
    if key >= "облескивавший" {
        return m26(key);
    }
    if key >= "номинировавшийся" {
        return m25(key);
    }
    if key >= "натискавший" {
        return m24(key);
    }
    if key >= "наносящийся" {
        return m23(key);
    }
    if key >= "надрызгавший" {
        return m22(key);
    }
    if key >= "мрачневший" {
        return m21(key);
    }
    if key >= "лицезрящий" {
        return m20(key);
    }
    if key >= "кончавший" {
        return m19(key);
    }
    if key >= "исчисленный" {
        return m18(key);
    }
    if key >= "иллюминованный" {
        return m17(key);
    }
    if key >= "зоримый" {
        return m16(key);
    }
    if key >= "затравленный" {
        return m15(key);
    }
    if key >= "запуливший" {
        return m14(key);
    }
    if key >= "залупавший" {
        return m13(key);
    }
    if key >= "задергивающийся" {
        return m12(key);
    }
    if key >= "жмурившийся" {
        return m11(key);
    }
    if key >= "дорубавший" {
        return m10(key);
    }
    if key >= "довертываемый" {
        return m9(key);
    }
    if key >= "гранивший" {
        return m8(key);
    }
    if key >= "вытопленный" {
        return m7(key);
    }
    if key >= "выпахивавший" {
        return m6(key);
    }
    if key >= "выделивший" {
        return m5(key);
    }
    if key >= "вскормивший" {
        return m4(key);
    }
    if key >= "возвысившийся" {
        return m3(key);
    }
    if key >= "взаимодействовавший" {
        return m2(key);
    }
    if key >= "блокирующий" {
        return m1(key);
    }
    m0(key)
}

